def calculate_min_cost(n, k, s):
    if k > n:
        return -1

    # Calculate the cost of adding a subsequence of length i
    def cost_of_subsequence(i):
        return n - i

    # Calculate the minimum cost to obtain a set of size k
    def min_cost_to_set(k):
        if k == 0:
            return 0
        elif k == 1:
            return cost_of_subsequence(1)
        else:
            # The minimum cost to obtain a set of size k is the cost of the first subsequence
            # plus the minimum cost to obtain a set of size k-1
            return cost_of_subsequence(1) + min_cost_to_set(k-1)

