def can_construct_square(n, m, tiles):
    def is_symmetric(grid):
        for i in range(m):
            for j in range(m):
                if grid[i][j] != grid[j][i]:
                    return False
        return True

    def place_tiles(grid, x, y, tile):
        if x + 2 > m or y + 2 > m:
            return False
        grid[x][y] = tile[0]
        grid[x][y+1] = tile[1]
        grid[x+1][y] = tile[2]
        grid[x+1][y+1] = tile[3]
        return True

    def remove_tiles(grid, x, y):
        grid[x][y] = 0
        grid[x][y+1] = 0
        grid[x+1][y] = 0
        grid[x+1][y+1] = 0

    def backtrack(grid, pos):
        if pos == m * m:
            return is_symmetric(grid)
        i, j = pos // m, pos % m
        for tile in tiles:
            if place_tiles(grid, i, j, tile):
                if backtrack(grid, pos + 1):
                    return True
                remove_tiles(grid, i, j)
        return False

