def count_wins(t, w, b):
    if w == b:
        return 1
    lcm_wb = lcm(w, b)
    max_steps_w = t // w
    max_steps_b = t // b
    max_steps_lcm = t // lcm_wb

    wins_w = 0
    wins_b = 0

    for steps in range(1, max_steps_w + 1):
        if steps * w <= t:
            wins_w += 1

    for steps in range(1, max_steps_b + 1):
        if steps * b <= t:
            wins_b += 1

    for steps in range(1, max_steps_lcm + 1):
        if steps * lcm_wb <= t:
            wins_w -= 1
            wins_b -= 1

    return wins_w, wins_b

def probability_tie(t, w, b):
    wins_w, wins_b = count_wins(t, w, b)
    total_wins = wins_w + wins_b
    if total_wins == 0:
        return Fraction(1, 1)
    return Fraction(wins_w, total_wins)

