def count_prefixes(n, x, s):
    balance = 0
    count = 0
    prefix_count = 0
    seen_balances = {0: 1}

    for i in range(n):
        if s[i] == '0':
            balance -= 1
        else:
            balance += 1

        if balance == x:
            prefix_count += 1

        if balance - x in seen_balances:
            prefix_count += seen_balances[balance - x]

        if balance in seen_balances:
            seen_balances[balance] += 1
        else:
            seen_balances[balance] = 1

    if balance == x:
        prefix_count += 1

    if balance == 0 and x == 0:
        prefix_count += 1

    if x == 0 and balance != 0:
        return -1

    return prefix_count

def process_test_case(n, x, s):
    if n == 0:
        return 1 if x == 0 else 0

    if n == 1:
        if s == '0':
            return 1 if x == 0 else 0
        else:
            return 1 if x == 1 else 0

    if x == 0 and s.count('0') != s.count('1'):
        return -1

    if x == 0 and s.count('0') == s.count('1'):
        return 1

    if x == 1 and s.count('0') == s.count('1'):
        return -1

    if x == 1 and s.count('0') != s.count('1'):
        return 1

    return count_prefixes(n, x, s)

