def count_prefixes(n, x, s):
    balance = 0
    count = 0
    for i in range(n):
        balance += 1 if s[i] == '1' else -1
        if balance == x:
            count += 1
    return count

def process_test_case(n, x, s):
    if x == 0:
        return 1
    if s.count('0') == 0 or s.count('1') == 0:
        return -1
    if x > 0:
        if s[0] == '1':
            return -1
        return 1 + count_prefixes(n, x - 1, s[1:])
    else:
        if s[0] == '0':
            return -1
        return 1 + count_prefixes(n, x + 1, s[1:])

def main():
