    index += 1
    results = []

    for _ in range(T):
        n = int(data[index])
        x = int(data[index + 1])
        s = data[index + 2]
        index += 3

        result = process_test_case(n, x, s)
        results.append(result)

    for result in results:
        print(result)

if __name__ == "__main__":
